<?php
declare(strict_types=1);
function projectPlanValidate(mixed $raw):array {
 $c=studioRecord($raw);$out=['schemaVersion'=>1,'purpose'=>studioText($c['purpose']??'',2000),'outcome'=>studioText($c['outcome']??'',2000),'startDate'=>govDate($c['startDate']??''),'states'=>[],'stakeholders'=>[],'tasks'=>[],'gates'=>[]];
 $states=studioRecord($c['states']??[]);if(array_diff(array_keys($states),['landscape','readiness','governance']))fail(422,'Unbekannte Zustandsart.');foreach($states as $kind=>$pair){$pair=studioRecord($pair);$out['states'][$kind]=['start'=>studioText($pair['start']??'',32),'target'=>studioText($pair['target']??'',32)];foreach($out['states'][$kind] as $id)if($id!==''&&!preg_match('/^[a-f0-9]{32}$/D',$id))fail(422,'Ungültige Momentaufnahme.');if(($pair['start']??'')!==''&&($pair['start']??'')===($pair['target']??''))fail(422,'Start- und Zielbild müssen unterschiedliche Momentaufnahmen sein.');}
 $people=[];foreach(govUniqueRows($c['stakeholders']??[],200) as $p){$id=labName($p['id']);$people[$id]=true;$out['stakeholders'][]=['id'=>$id,'name'=>labName($p['name']??null,180),'role'=>studioText($p['role']??'',180),'source'=>studioText($p['source']??'',200)];}
 $ids=[];foreach(govUniqueRows($c['tasks']??[],300) as $t){$owner=govOptionalId($t['owner']??'');if($owner&&!isset($people[$owner]))fail(422,'Verantwortlicher Stakeholder fehlt.');$id=labName($t['id']);$ids[$id]=true;$out['tasks'][]=['id'=>$id,'title'=>labName($t['title']??null,180),'track'=>studioEnum($t['track']??'it',['it','digital','ai','change']),'phase'=>studioEnum($t['phase']??'discover',['discover','pilot','validate','rollout','operate']),'status'=>studioEnum($t['status']??'todo',['todo','doing','blocked','done']),'owner'=>$owner,'days'=>govNumber($t['days']??1,0,3650),'depends'=>labList($t['depends']??[],100),'criterion'=>studioText($t['criterion']??'',2000),'evidence'=>studioText($t['evidence']??'',3000),'notes'=>studioText($t['notes']??'',3000)];}
 $edges=[];foreach($out['tasks'] as $t){foreach($t['depends'] as $id)if(!is_string($id)||!isset($ids[$id])||$id===$t['id'])fail(422,'Abhängigkeiten benötigen andere vorhandene Arbeitspakete.');if(count(array_unique($t['depends']))!==count($t['depends']))fail(422,'Abhängigkeit doppelt gewählt.');$edges[$t['id']]=$t['depends'];}
 $marks=[];$visit=function($id)use(&$visit,$edges,&$marks){if(($marks[$id]??0)===1)fail(422,'Die Projektabhängigkeiten enthalten einen Kreis.');if(($marks[$id]??0)===2)return;$marks[$id]=1;foreach($edges[$id]??[] as $before)$visit($before);$marks[$id]=2;};foreach(array_keys($ids) as $id)$visit($id);
 foreach(govUniqueRows($c['gates']??[],30) as $g){$owner=govOptionalId($g['owner']??'');if($owner&&!isset($people[$owner]))fail(422,'Gate-Verantwortung fehlt.');$out['gates'][]=['id'=>$g['id'],'phase'=>studioEnum($g['phase']??'pilot',['discover','pilot','validate','rollout','operate']),'title'=>labName($g['title']??null,180),'criterion'=>studioText($g['criterion']??'',2000),'decision'=>studioEnum($g['decision']??'open',['open','go','hold','stop']),'owner'=>$owner,'evidence'=>studioText($g['evidence']??'',3000)];if($g['decision']==='go'&&(!$owner||!trim($g['evidence']??'')))fail(422,'Ein Go benötigt Verantwortung und Entscheidungsnachweis.');}
 return $out;
}
function projectPlanStateAccess(array $u,string $pid,array $c,?array $old=null):void {
 foreach($c['states'] as $kind=>$pair)foreach($pair as $side=>$id){if(!$id||($old['states'][$kind][$side]??'')===$id)continue;labAccess($u,$pid,$kind);$r=one('SELECT kind FROM lab_states WHERE id=? AND project_id=?',[$id,$pid]);if(!$r||$r['kind']!==$kind)fail(422,'Momentaufnahme gehört nicht zu diesem Projekt und Zustandsbereich.');}
}
function projectStateCapture(array $u,array $d):array {
 $pid=textField($d,'project',32);labAccess($u,$pid,'rollout');return transaction(function()use($u,$pid,$d){$o=labObject($u,textField($d,'id',32));if($o['project_id']!==$pid||!in_array($o['kind'],['landscape','readiness','governance'],true))fail(404,'Start-/Zielquelle nicht verfügbar.');if(($d['version']??null)!==$o['version'])fail(409,'Die Quelle wurde geändert. Bitte den gespeicherten Stand neu laden.');
  if((int)query('SELECT COUNT(*) FROM lab_states WHERE project_id=?',[$pid])->fetchColumn()>=120)fail(413,'Höchstens 120 Momentaufnahmen pro Projekt.');
  $name=labName($d['name']??$o['name'],120);$companions=[];
  if(in_array($o['kind'],['landscape','readiness'],true)){try{labAccess($u,$pid,'governance');foreach(all('SELECT id,content FROM lab_objects WHERE project_id=? AND kind="governance" ORDER BY name,id',[$pid]) as $g)if((json_decode($g['content'],true)[$o['kind']]??'')===$o['id'])$companions[]=labObject($u,$g['id']);}catch(ApiError){}}
  if($o['kind']==='governance'&&($o['content']['landscape']??'')){try{$l=labObject($u,$o['content']['landscape']);if($l['kind']==='landscape'&&$l['project_id']===$pid)$companions[]=$l;}catch(ApiError){}}
  $sid=id();$payload=['content'=>$o['content'],'companions'=>$companions];$encoded=labJson($payload);if(workspaceBytes(project($u,$pid))+strlen($encoded)>SPACE_LIMIT)fail(413,'Der Workspace-Speicher ist voll.');query('INSERT INTO lab_states(id,project_id,kind,source_id,source_version,name,content,created_by,created_at) VALUES(?,?,?,?,?,?,?,?,?)',[$sid,$pid,$o['kind'],$o['id'],$o['version'],$name,$encoded,$u['id'],now()]);audit($u['id'],'lab.state.capture',['project'=>$pid,'source'=>$o['id'],'version'=>$o['version']]);return ['state'=>projectStatePublic($u,one('SELECT * FROM lab_states WHERE id=?',[$sid]))];});
}
function projectStatePublic(array $u,array $r):array {
 $allowed=true;try{labAccess($u,$r['project_id'],$r['kind']);}catch(ApiError){$allowed=false;}
 $out=['id'=>$r['id'],'kind'=>$r['kind'],'name'=>$allowed?$r['name']:'Zustand · Bereich nicht freigegeben','source'=>$allowed?$r['source_id']:null,'version'=>(int)$r['source_version'],'createdAt'=>$r['created_at'],'available'=>$allowed];if(!$allowed)return $out;
 $p=json_decode($r['content'],true);$out['content']=labStructuredContent($r['kind'],$p['content']);$out['companions']=[];foreach($p['companions']??[] as $g){try{labAccess($u,$r['project_id'],$g['kind']);$g['content']=labStructuredContent($g['kind'],$g['content']);$out['companions'][]=$g;}catch(ApiError){}}return $out;
}
function projectPlanContext(array $u,array $d):array {
 $pid=textField($d,'project',32);labAccess($u,$pid,'rollout');$states=array_map(fn($r)=>projectStatePublic($u,$r),all('SELECT * FROM lab_states WHERE project_id=? ORDER BY created_at DESC,id',[$pid]));$objects=[];foreach(all('SELECT id,kind FROM lab_objects WHERE project_id=? AND kind IN ("landscape","readiness","governance") ORDER BY kind,name,id',[$pid]) as $r){try{$o=labObject($u,$r['id']);unset($o['content']);$objects[]=$o;}catch(ApiError){}}return ['states'=>$states,'objects'=>$objects];
}
